  public Factory App=new();public HttpClient Admin=null!,A=null!,B=null!;public Guid AId,BId,Handout,Question,Course,Class,CanonicalEdition,Occurrence;public string Canonical="",ContextKey="fixture/source.docx";
  public static async Task<Setup> Create(){var c=new Setup();c.Admin=await c.App.Login("bank-admin",true);
   async Task<(HttpClient,Guid)> Teacher(string name){var row=await Factory.Post(c.Admin,"/api/admin/catalog/staff",new{name,role="teacher"});var id=row.GetProperty("id").GetGuid();var invite=await Factory.Post(c.Admin,$"/api/admin/staff/{id}/invite",new{});var client=await c.App.Login(name);await Factory.Post(client,"/api/auth/bind",new{code=invite.GetProperty("code").GetString()});return(client,id);}
   (c.A,c.AId)=await Teacher("甲教师");(c.B,c.BId)=await Teacher("乙教师");
   using var scope=c.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Data>();var library=scope.ServiceProvider.GetRequiredService<LibraryEditDb>();await library.Database.ExecuteSqlRawAsync(library.Database.GenerateCreateScript().Replace("CREATE TABLE ","CREATE TABLE IF NOT EXISTS ").Replace("CREATE UNIQUE INDEX ","CREATE UNIQUE INDEX IF NOT EXISTS ").Replace("CREATE INDEX ","CREATE INDEX IF NOT EXISTS "));
   var campus=new Campus{Name="校区"};var course=new Course{Name="2026·秋季·初一·数学·推荐生"};var cl=new SchoolClass{Name="甲班",OwnerStaffId=c.AId,CampusId=campus.Id};var l=new Lecture{ClassId=cl.Id,CourseId=course.Id,Sequence=3,Title="一元一次方程"};var h=new Handout{LectureId=l.Id,State="draft",Revision=1,FileName="方程讲义.docx",NormalizedKey=c.ContextKey};var w=WordDocuments.W;var xml=new XElement(w+"p",new XElement(w+"r",new XElement(w+"t","例1：Solve x + 3 = 5."))).ToString();var q=new Question{HandoutId=h.Id,Order=1,Family="例",Label="例1",Confirmed=false,BlocksJson=Json.Write(new[]{new ContentBlock(xml,"解方程 x + 3 = 5","paragraph")}),PreviewsJson=Json.Write(new[]{"fixture/q.png"})};db.AddRange(campus,course,cl,l,h,q,new Assignment{StaffId=c.AId,ClassId=cl.Id,CourseId=course.Id});await db.SaveChangesAsync();c.Handout=h.Id;c.Question=q.Id;c.Course=course.Id;c.Class=cl.Id;
   var objects=scope.ServiceProvider.GetRequiredService<IObjects>();var path=Path.Combine(c.App.Root,"source.docx");using(var doc=WordprocessingDocument.Create(path,DocumentFormat.OpenXml.WordprocessingDocumentType.Document)){var main=doc.AddMainDocumentPart();main.Document=new DocumentFormat.OpenXml.Wordprocessing.Document(new DocumentFormat.OpenXml.Wordprocessing.Body(new DocumentFormat.OpenXml.Wordprocessing.Paragraph(new DocumentFormat.OpenXml.Wordprocessing.Run(new DocumentFormat.OpenXml.Wordprocessing.Text("source")))));main.Document.Save();}await using(var input=File.OpenRead(path))await objects.Put(c.ContextKey,input,WordDocuments.DocxType);await objects.Put("fixture/q.png",new MemoryStream(Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=")),"image/png");
   return c;
  }
  public async Task Confirm(bool value=true){using var scope=App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Data>();await db.Questions.Where(q=>q.Id==Question).ExecuteUpdateAsync(s=>s.SetProperty(q=>q.Confirmed,value).SetProperty(q=>q.Revision,q=>q.Revision+1));}
  public async Task Shared(){using var scope=App.Services.CreateScope();var library=scope.ServiceProvider.GetRequiredService<LibraryEditDb>();var objects=scope.ServiceProvider.GetRequiredService<IObjects>();var blobs=scope.ServiceProvider.GetRequiredService<LibraryObjects>();var source=await File.ReadAllBytesAsync(Path.Combine(App.Root,"source.docx"));var context=await blobs.Put(source,".docx",WordDocuments.DocxType,default);var canonical=await scope.ServiceProvider.GetRequiredService<LibraryCanonicalImport>().PlainBankQuestion("Shared equation x + 4 = 9","数学","初中","初一",["一元一次方程"],"{}",default);Canonical=canonical.Id;library.Canonicals.Add(canonical);
   var materialId=Guid.NewGuid();var hash=LibraryObjects.Sha(source);var original=CourseMaterials.SourceKey(Course,hash,".docx");await objects.Put(original,new MemoryStream(source),WordDocuments.DocxType);var m=new CourseMaterial(materialId,Course,[],"handout","both","共享方程教材",hash,original,"共享方程教材.docx",1,source.Length,OriginalRelativePath:"数学/共享方程教材.docx");async Task Put(string key,object value)=>await objects.Put(key,new MemoryStream(Encoding.UTF8.GetBytes(Json.Write(value))),"application/json");await Put(CourseMaterials.LibraryKey,new CourseMaterialLibraryIndex(1,1,[new(Course,true)]));await Put(CourseMaterials.ManifestKey(Course),new CourseMaterialManifest(1,Course,[m]));
   var o=new LibraryOccurrence(Guid.NewGuid(),1,"例2",canonical.Id,0,1,"hash","{}",true,[],"数学","初中","初一",["一元一次方程"]);var edition=new LibraryEdition{MaterialId=materialId,Number=1,ActorStaffId=AId,ActorName="甲教师",Title=m.Title,DocxKey=context.Key,DocxSha256=context.Hash,OccurrencesJson=Json.Write(new[]{o})};library.Heads.Add(new(){MaterialId=materialId,CourseId=Course,Revision=1});await library.SaveChangesAsync();library.Editions.Add(edition);await library.SaveChangesAsync();await library.Heads.Where(h=>h.MaterialId==materialId).ExecuteUpdateAsync(s=>s.SetProperty(h=>h.CurrentEditionId,edition.Id));CanonicalEdition=edition.Id;Occurrence=o.Id;
  }
  public async ValueTask DisposeAsync(){Admin.Dispose();A.Dispose();B.Dispose();await App.DisposeAsync();}
