 static async Task<JsonElement> Get(HttpClient c,string url){var r=await c.GetAsync(url);Assert.True(r.IsSuccessStatusCode,await r.Content.ReadAsStringAsync());return await r.Content.ReadFromJsonAsync<JsonElement>();}
 static MaterialPaperInput Input(JsonElement item,Guid? request=null)=>new("方程练习","第3讲","2026-11-07",[new(item.GetProperty("id").GetString()!,item.GetProperty("revision").GetString()!)],request??Guid.NewGuid());
 [Fact] public async Task ReviewImmediatelyEntersAndUndoWithdrawsWithoutImportJobs(){await using var c=await Setup.Create();Assert.Equal(0,(await Get(c.A,"/api/material-question-bank")).GetProperty("total").GetInt32());await Factory.Post(c.A,$"/api/handouts/{c.Handout}/confirm-all",new{revision=1});var list=await Get(c.A,"/api/material-question-bank?q=方程&subject=数学&grade=初一");Assert.Equal(1,list.GetProperty("total").GetInt32());Assert.Equal(0,(await Get(c.B,"/api/material-question-bank")).GetProperty("total").GetInt32());var item=list.GetProperty("items")[0];Assert.Equal(HttpStatusCode.NotFound,(await c.B.GetAsync("/api/material-question-bank/question?id="+item.GetProperty("id").GetString())).StatusCode);await c.Confirm(false);Assert.Equal(0,(await Get(c.A,"/api/material-question-bank")).GetProperty("total").GetInt32());Assert.Equal(HttpStatusCode.Conflict,(await c.A.PostAsJsonAsync("/api/material-question-bank/papers",Input(item))).StatusCode);using var scope=c.App.Services.CreateScope();Assert.Empty(await scope.ServiceProvider.GetRequiredService<Data>().Work.ToArrayAsync());}
 [Fact] public async Task SharedCanonicalApprovalAndRevocationAreImmediate(){await using var c=await Setup.Create();await c.Shared();Assert.Equal(0,(await Get(c.B,"/api/material-question-bank")).GetProperty("total").GetInt32());await Factory.Post(c.Admin,$"/api/central-research/material-versions/{c.CanonicalEdition}/questions/{c.Occurrence}/review",new{revision=1,reviewRevision=0,confirmContent=true,confirmBoundary=true});var list=await Get(c.B,"/api/material-question-bank?tag=一元一次方程&scope=shared");Assert.Equal(1,list.GetProperty("total").GetInt32());Assert.True(list.GetProperty("items")[0].GetProperty("shared").GetBoolean());using(var s=c.App.Services.CreateScope()){var l=s.ServiceProvider.GetRequiredService<LibraryEditDb>();await l.Canonicals.Where(q=>q.Id==c.Canonical).ExecuteUpdateAsync(s=>s.SetProperty(q=>q.ReviewState,"pending"));}Assert.Equal(0,(await Get(c.B,"/api/material-question-bank")).GetProperty("total").GetInt32());}
 [Fact] public async Task SelectionIsIdempotentOrderedFrozenAndOwnerScoped(){await using var c=await Setup.Create();await c.Confirm();var item=(await Get(c.A,"/api/material-question-bank")).GetProperty("items")[0];var input=Input(item);var first=await Factory.Post(c.A,"/api/material-question-bank/papers",input);var second=await Factory.Post(c.A,"/api/material-question-bank/papers",input);Assert.Equal(first.GetProperty("id").GetGuid(),second.GetProperty("id").GetGuid());Assert.Equal(HttpStatusCode.Conflict,(await c.A.PostAsJsonAsync("/api/material-question-bank/papers",input with{Title="changed"})).StatusCode);var id=first.GetProperty("id").GetGuid();Assert.Equal(HttpStatusCode.Forbidden,(await c.B.GetAsync($"/api/material-question-bank/papers/{id}")).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.B.GetAsync($"/api/exports/{id}/download?format=pdf")).StatusCode);Assert.Single((await Get(c.A,"/api/exports")).EnumerateArray());using var scope=c.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Data>();var doc=await db.Documents.SingleAsync();var snap=Json.Read<MaterialPaperSnapshot>(doc.SnapshotJson);Assert.StartsWith("library-content/sha256/",snap.Questions[0].SourceKey);Assert.NotNull(snap.Questions[0].SourceHash);Assert.Single(await db.Work.ToArrayAsync());}
 [Fact] public async Task GeneratesRealWordAndPdfWithSourceAndRetainsOriginal(){await using var c=await Setup.Create();await c.Confirm();var item=(await Get(c.A,"/api/material-question-bank")).GetProperty("items")[0];var input=Input(item);var result=await Factory.Post(c.A,"/api/material-question-bank/papers",input);var id=result.GetProperty("id").GetGuid();using(var workerScope=c.App.Services.CreateScope()){Assert.True(await workerScope.ServiceProvider.GetRequiredService<DocumentWorker>().Tick(default));Assert.Equal("done",(await workerScope.ServiceProvider.GetRequiredService<Data>().Work.SingleAsync()).State);}var status=await Get(c.A,$"/api/material-question-bank/papers/{id}");Assert.Equal("ready",status.GetProperty("state").GetString());var f=await Get(c.A,$"/api/exports/{id}/download?format=pdf");var bytes=await c.A.GetByteArrayAsync(new Uri(f.GetProperty("url").GetString()!).PathAndQuery);using var pdf=PdfDocument.Open(bytes);Assert.Equal(1,pdf.NumberOfPages);Assert.Contains("x",pdf.GetPage(1).Text);var dir=Path.GetFullPath("material-bank-20261107/rendered");Directory.CreateDirectory(dir);await File.WriteAllBytesAsync(Path.Combine(dir,"selected.pdf"),bytes);var word=await Get(c.A,$"/api/exports/{id}/download?format=docx");await File.WriteAllBytesAsync(Path.Combine(dir,"selected.docx"),await c.A.GetByteArrayAsync(new Uri(word.GetProperty("url").GetString()!).PathAndQuery));using var scope=c.App.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<Data>();Assert.Equal(c.ContextKey,(await db.Handouts.SingleAsync()).NormalizedKey);Assert.Equal(1,await db.Questions.CountAsync());}
 [Fact] public async Task MissingPreviewAndUnsafeBoundaryAreNotIndexed(){await using var c=await Setup.Create();await c.Confirm();using(var scope=c.App.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Data>();await db.Questions.Where(q=>q.Id==c.Question).ExecuteUpdateAsync(s=>s.SetProperty(q=>q.PreviewsJson,"[]"));}Assert.Equal(0,(await Get(c.A,"/api/material-question-bank")).GetProperty("total").GetInt32());}
 [Fact] public async Task RetryIsOwnerScopedAndDoesNotDuplicateWork(){await using var c=await Setup.Create();await c.Confirm();var item=(await Get(c.A,"/api/material-question-bank")).GetProperty("items")[0];var result=await Factory.Post(c.A,"/api/material-question-bank/papers",Input(item));var id=result.GetProperty("id").GetGuid();using(var s=c.App.Services.CreateScope()){var db=s.ServiceProvider.GetRequiredService<Data>();await db.Documents.Where(d=>d.Id==id).ExecuteUpdateAsync(s=>s.SetProperty(d=>d.State,"failed").SetProperty(d=>d.Error,"retryable"));await db.Work.Where(w=>w.Id==id).ExecuteUpdateAsync(s=>s.SetProperty(w=>w.State,"failed"));}Assert.Equal(HttpStatusCode.Forbidden,(await c.B.PostAsJsonAsync($"/api/material-question-bank/papers/{id}/retry",new{})).StatusCode);await Factory.Post(c.A,$"/api/material-question-bank/papers/{id}/retry",new{});await Factory.Post(c.A,$"/api/material-question-bank/papers/{id}/retry",new{});using var scope=c.App.Services.CreateScope();var data=scope.ServiceProvider.GetRequiredService<Data>();Assert.Single(await data.Work.ToArrayAsync());Assert.Equal("queued",(await data.Work.SingleAsync()).State);Assert.Null((await data.Documents.SingleAsync()).Error);}
 [Fact] public async Task MixedFormulaAndImageQuestionsKeepOrderAndTwoPerPage(){await using var c=await Setup.Create();using(var scope=c.App.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Data>();var fixture=Path.Combine(AppContext.BaseDirectory,"fixtures","booklet-layout-source.docx");await using(var input=File.OpenRead(fixture))await scope.ServiceProvider.GetRequiredService<IObjects>().Put(c.ContextKey,input,WordDocuments.DocxType);using var source=WordprocessingDocument.Open(fixture,false);var w=WordDocuments.W;var root=XElement.Parse(source.MainDocumentPart!.Document!.OuterXml);var rows=root.Descendants(w+"tbl").First().Elements(w+"tr").ToArray();db.Questions.RemoveRange(await db.Questions.ToArrayAsync());for(var i=0;i<rows.Length;i++){var blocks=rows[i].Elements(w+"tc").Last().Elements(w+"p").TakeWhile(p=>!string.Concat(p.Descendants(w+"t").Select(t=>t.Value)).Contains("解题过程")).Select(WordDocuments.Block).ToArray();db.Questions.Add(new Question{HandoutId=c.Handout,Order=i+1,Family="例",Label="例"+(i+1),Confirmed=true,BlocksJson=Json.Write(blocks),PreviewsJson=Json.Write(new[]{"fixture/q.png"})});}await db.SaveChangesAsync();}
 var items=(await Get(c.A,"/api/material-question-bank")).GetProperty("items").EnumerateArray().ToArray();Assert.Equal(3,items.Length);var inputPaper=new MaterialPaperInput("公式与图形混合练习","第3讲","2026-11-07",items.Reverse().Select(q=>new BankSelection(q.GetProperty("id").GetString()!,q.GetProperty("revision").GetString()!)).ToArray(),Guid.NewGuid());var result=await Factory.Post(c.A,"/api/material-question-bank/papers",inputPaper);var id=result.GetProperty("id").GetGuid();await c.App.Run("question-paper",id);using var outputScope=c.App.Services.CreateScope();var data=outputScope.ServiceProvider.GetRequiredService<Data>();var d=await data.Documents.SingleAsync();Assert.Equal(inputPaper.Questions.Select(q=>q.Id),Json.Read<MaterialPaperSnapshot>(d.SnapshotJson).Questions.Select(q=>q.Id));var files=outputScope.ServiceProvider.GetRequiredService<IObjects>();await using var word=await files.Get(d.DocxKey);using var pack=WordprocessingDocument.Open(word,false);Assert.Contains("oMath",pack.MainDocumentPart!.Document!.OuterXml);Assert.NotEmpty(pack.MainDocumentPart.ImageParts);await using var pdfStream=await files.Get(d.PdfKey);using var memory=new MemoryStream();await pdfStream.CopyToAsync(memory);using var pdf=PdfDocument.Open(memory.ToArray());Assert.Equal(2,pdf.NumberOfPages);Assert.Equal(1,pdf.GetPages().Sum(p=>p.NumberOfImages));var outDir=Path.GetFullPath("material-bank-20261107/rendered");Directory.CreateDirectory(outDir);await File.WriteAllBytesAsync(Path.Combine(outDir,"mixed.pdf"),memory.ToArray());}
 [Fact] public async Task MultipleSourcesIncludeApprovedCanonicalAndSnapshotStaysFixed(){await using var c=await Setup.Create();await c.Confirm();await c.Shared();await Factory.Post(c.Admin,$"/api/central-research/material-versions/{c.CanonicalEdition}/questions/{c.Occurrence}/review",new{revision=1,reviewRevision=0,confirmContent=true,confirmBoundary=true});var items=(await Get(c.A,"/api/material-question-bank")).GetProperty("items").EnumerateArray().ToArray();Assert.Equal(2,items.Length);var input=new MaterialPaperInput("跨教材练习","第3讲","2026-11-07",items.Select(q=>new BankSelection(q.GetProperty("id").GetString()!,q.GetProperty("revision").GetString()!)).ToArray(),Guid.NewGuid());var created=await Factory.Post(c.A,"/api/material-question-bank/papers",input);await c.Confirm(false);await c.App.Run("question-paper",created.GetProperty("id").GetGuid());var download=await Get(c.A,$"/api/exports/{created.GetProperty("id").GetGuid()}/download?format=pdf");var bytes=await c.A.GetByteArrayAsync(new Uri(download.GetProperty("url").GetString()!).PathAndQuery);using var pdf=PdfDocument.Open(bytes);Assert.Equal(1,pdf.NumberOfPages);var text=pdf.GetPage(1).Text;Assert.Contains("Solve",text);Assert.Contains("Shared",text);Assert.Contains("来源",text);}

 [Fact] public async Task BeyondHalfPageStandsAloneAndRetainsEveryLine(){await using var c=await Setup.Create();await c.Confirm();using(var scope=c.App.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<Data>();var q=await db.Questions.SingleAsync();var w=WordDocuments.W;q.BlocksJson=Json.Write(Enumerable.Range(1,22).Select(i=>new ContentBlock(new XElement(w+"p",new XElement(w+"r",new XElement(w+"t","STEP"+i.ToString("00")+" Show all reasoning and calculations."))).ToString(),"STEP"+i,"paragraph")));db.Questions.Add(new Question{HandoutId=c.Handout,Order=2,Family="例",Label="例2",Confirmed=true,BlocksJson=Json.Write(new[]{new ContentBlock(new XElement(w+"p",new XElement(w+"r",new XElement(w+"t","SHORTQUESTION x + 1 = 2"))).ToString(),"SHORTQUESTION","paragraph")}),PreviewsJson=Json.Write(new[]{"fixture/q.png"})});await db.SaveChangesAsync();}var items=(await Get(c.A,"/api/material-question-bank")).GetProperty("items").EnumerateArray().ToArray();var input=new MaterialPaperInput("分页验收","第3讲","2026-11-07",items.Select(q=>new BankSelection(q.GetProperty("id").GetString()!,q.GetProperty("revision").GetString()!)).ToArray(),Guid.NewGuid());var result=await Factory.Post(c.A,"/api/material-question-bank/papers",input);var id=result.GetProperty("id").GetGuid();await c.App.Run("question-paper",id);var download=await Get(c.A,$"/api/exports/{id}/download?format=pdf");using var pdf=PdfDocument.Open(await c.A.GetByteArrayAsync(new Uri(download.GetProperty("url").GetString()!).PathAndQuery));Assert.Equal(2,pdf.NumberOfPages);Assert.Contains("STEP22",pdf.GetPage(1).Text);Assert.DoesNotContain("SHORTQUESTION",pdf.GetPage(1).Text);Assert.Contains("SHORTQUESTION",pdf.GetPage(2).Text);}


 [Fact]
 public async Task TeacherCanQueueAndTrackOwnSelectionBeforeRenderingFinishes()
 {
     await using var c = await Setup.Create();
     await c.Confirm();
     var item = (await Get(c.A, "/api/material-question-bank")).GetProperty("items")[0];
     var generated = await Factory.Post(c.A, "/api/material-question-bank/papers", Input(item));
     var documentId = generated.GetProperty("id").GetGuid();
     using var scope = c.App.Services.CreateScope();
     var db = scope.ServiceProvider.GetRequiredService<Data>();
     var campus = await db.Campuses.SingleAsync();
     var device = new Device { CampusId = campus.Id, Name = "验收设备", Enabled = true };
     var printer = new Printer { CampusId = campus.Id, DeviceId = device.Id, Name = "验收打印机", Enabled = true };
     db.AddRange(device, printer);
     await db.SaveChangesAsync();
     var request = new { documentIds = new[] { documentId }, printerId = printer.Id, copies = 1,
         duplex = false, requestKey = Guid.NewGuid().ToString(), waitForDocuments = true };
     await Factory.Post(c.A, "/api/print-jobs", request);
     var row = Assert.Single((await Get(c.A, "/api/print-jobs")).EnumerateArray());
     Assert.Equal(documentId, row.GetProperty("documentId").GetGuid());
     Assert.Equal("preparing", row.GetProperty("state").GetString());
     Assert.Empty((await Get(c.B, "/api/print-jobs")).EnumerateArray());
     Assert.Equal(HttpStatusCode.Forbidden, (await c.B.PostAsJsonAsync("/api/print-jobs", request)).StatusCode);
 }
